    "pertanyaan": "Harga sebuah laptop didiskon 20%, kemudian didiskon lagi 10% dari harga setelah diskon pertama. Jika harga akhir laptop tersebut Rp5.760.000, maka harga awal laptop tersebut adalah ...",
