    "tingkat": "HOTS",
    "pertanyaan": "Piagam Madinah (Mitsaq al-Madinah) yang disusun Nabi Muhammad SAW setelah hijrah ke Madinah dianggap sebagai salah satu dokumen konstitusional tertua di dunia. Prinsip yang paling revolusioner dari piagam ini untuk zamannya adalah ...",
