    "pembahasan": "Jawaban: B Pernyataan \"Tidak semua A adalah B\" secara logis setara dengan \"Sebagian A bukan B\" atau \"Ada A yang bukan B.\" Dalam logika formal: ¬∀x(Px → Qx) ≡ ∃x(Px ∧ ¬Qx). Jadi \"Tidak semua mahasiswa ber-IPK tinggi memiliki keterampilan berpikir kritis yang baik\" = \"Sebagian mahasiswa ber-IPK tinggi tidak memiliki keterampilan berpikir kritis yang baik.\" Opsi A terlalu kuat (semua). Opsi C meniadakan semua. Opsi D membalik hubungan. Opsi E membuat generalisasi yang tidak warranted."
