      "B": "Kebebasan beragama dijamin tetapi setiap warga wajib memeluk salah satu agama yang diakui",
      "C": "Agama adalah urusan pribadi yang tidak boleh dibahas di ruang publik",
      "D": "Negara tidak boleh mengatur kehidupan beragama warganya sama sekali",
      "E": "Dakwah harus dilakukan secara paksa demi kebaikan masyarakat"
