    "pertanyaan": "Seorang petani memiliki lahan seluas 120 hektar untuk ditanami padi dan jagung. Biaya per hektar untuk padi Rp2 juta dan jagung Rp1 juta, dengan modal tersedia Rp180 juta. Keuntungan per hektar padi Rp3 juta dan jagung Rp2 juta. Keuntungan maksimum yang dapat diperoleh petani adalah ...",
