    "pembahasan": "Jawaban: B f(x) = x² · ln(x). Gunakan aturan perkalian (product rule): f'(x) = (x²)' · ln(x) + x² · (ln x)'. f'(x) = 2x · ln(x) + x² · (1/x) = 2x · ln(x) + x. Bisa juga ditulis f'(x) = x(2 ln x + 1), yang setara dengan opsi B dan C. Opsi B lebih eksplisit."
