    "pertanyaan": "QS. Al-Baqarah ayat 256 menyatakan \"Laa ikraaha fid-diin\" (Tidak ada paksaan dalam beragama). Implementasi prinsip ini dalam konteks negara Indonesia yang berdasarkan Pancasila adalah ...",
