    "kunci": "B",
    "pembahasan": "Jawaban: B \"Laa ikraaha fid-diin\" menjamin kebebasan berkeyakinan tanpa paksaan. Dalam konteks Pancasila (sila 1: Ketuhanan Yang Maha Esa), implementasinya: kebebasan beragama dijamin secara konstitusional, tetapi setiap warga negara wajib memeluk salah satu agama yang diakui. Ini bukan kebebasan tanpa batas (A) atau pengabaian total (D), melainkan jaminan dengan kerangka yang teratur."
