    "pertanyaan": "Zakat profesi (zakat penghasilan) merupakan ijtihad kontemporer yang dianalogikan (qiyas) dengan zakat pertanian. Illat (alasan hukum) yang menjadi dasar pengqiyasan ini adalah ...",
