    "bagian": "Penalaran Matematika",
    "tingkat": "HOTS",
    "pertanyaan": "Konsep \"maslahah mursalah\" dalam usul fiqh memungkinkan penetapan hukum berdasarkan kemaslahatan umum meskipun tidak ada nash yang secara spesifik membahasnya. Contoh penerapan maslahah mursalah di era modern adalah ...",
