    "pertanyaan": "Sebuah kubus ABCD.EFGH memiliki panjang rusuk 6 cm. Titik P terletak di tengah rusuk BF dan titik Q terletak di tengah rusuk DH. Jarak titik P ke titik Q adalah ...",
