    "pembahasan": "Jawaban: A f(x) = 2x² - 8x + 6. Titik minimum pada x = -b/(2a) = 8/(2×2) = 2. f(2) = 2(4) - 8(2) + 6 = 8 - 16 + 6 = -2. Atau dengan melengkapkan kuadrat: f(x) = 2(x² - 4x) + 6 = 2(x² - 4x + 4 - 4) + 6 = 2(x-2)² - 8 + 6 = 2(x-2)² - 2. Nilai minimum = -2 saat x = 2."
