    "bagian": "Penalaran Matematika",
    "tingkat": "HOTS",
    "pertanyaan": "Bacalah teks berikut! \"Antibiotik telah menjadi pilar utama pengobatan modern sejak ditemukannya penisilin oleh Alexander Fleming pada 1928. Namun, penggunaan antibiotik yang berlebihan dan tidak tepat selama hampir satu abad telah menciptakan 'superbug' — bakteri yang resisten terhadap berbagai jenis antibiotik. WHO memperkirakan bahwa pada 2050, resistensi antimikroba (AMR) dapat menyebabkan 10 juta kematian per tahun jika tidak ada intervensi serius. Salah satu pendekatan inovatif adalah pengembangan terapi fag — penggunaan virus pemakan bakteri yang secara alami menargetkan strain bakteri tertentu tanpa merusak mikrobioma tubuh.\" Pernyataan yang paling tepat menggambarkan hubungan sebab-akibat dalam teks adalah ...",
