    "kunci": "B",
    "pembahasan": "Jawaban: B Hubungan sebab-akibat: penggunaan antibiotik yang berlebihan dan tidak tepat (sebab) → menciptakan 'superbug'/bakteri resisten (akibat). Opsi A salah — penemuan penisilin sendiri bukan penyebab, melainkan penggunaannya yang tidak tepat. Opsi C salah — WHO memperkirakan, bukan menyebabkan. Opsi D dan E kontradiktif dengan teks."
