    "tingkat": "HOTS",
    "pertanyaan": "Read the following passage! \"The concept of 'digital detox' has gained significant traction in recent years as researchers increasingly document the psychological toll of constant connectivity. A longitudinal study published in The Lancet Digital Health followed 5,000 adults over three years and found that those who limited screen time to less than two hours per day reported 40% lower rates of anxiety and 25% improvement in sleep quality. However, critics argue that digital detox is a privilege available primarily to those whose livelihoods do not depend on digital platforms, thus creating a new form of inequality.\" The main argument of the passage is ...",
