    "pembahasan": "Jawaban: C Barisan geometri: a = 3, r = 2. Sn = a(rⁿ - 1)/(r - 1) = 3(2ⁿ - 1). Sn &gt; 1000 → 3(2ⁿ - 1) &gt; 1000 → 2ⁿ - 1 &gt; 333,33 → 2ⁿ &gt; 334,33. Cek: 2⁸ = 256 (belum), 2⁹ = 512 (sudah). S₈ = 3(256-1) = 765. S₉ = 3(512-1) = 1533. Jadi n = 9 adalah saat pertama Sn melebihi 1000."
