      "B": "Muhammadiyah lebih menekankan purifikasi ajaran melalui kembali ke Al-Quran dan Sunnah, sementara NU lebih mempertahankan tradisi keilmuan pesantren dan mengakomodasi tradisi lokal",
      "C": "Keduanya memiliki pendekatan yang persis sama tanpa perbedaan",
